-- Specification migration: apply through A01/A02 implementation, not an implemented application.
PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE owners(id TEXT PRIMARY KEY,cookie_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,history_incomplete INTEGER NOT NULL DEFAULT 0 CHECK(history_incomplete IN(0,1)));
CREATE TABLE bank_manifests(version TEXT PRIMARY KEY,manifest_json TEXT NOT NULL,scope_hash TEXT NOT NULL,frozen_at TEXT);
CREATE TABLE problems(bank_version TEXT NOT NULL REFERENCES bank_manifests(version),id TEXT NOT NULL,content_hash TEXT NOT NULL,problem_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ready','needs_review','invalid')),PRIMARY KEY(bank_version,id));
CREATE TABLE packets(problem_hash TEXT NOT NULL,version TEXT NOT NULL,packet_json TEXT NOT NULL,ready INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(problem_hash,version));
CREATE TABLE sessions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES owners(id) ON DELETE CASCADE,version INTEGER NOT NULL CHECK(version>0),phase TEXT NOT NULL,state_json TEXT NOT NULL,problem_snapshot_json TEXT NOT NULL,active_run_id TEXT,expires_at TEXT NOT NULL);
CREATE TABLE requests(owner_id TEXT NOT NULL REFERENCES owners(id) ON DELETE CASCADE,request_id TEXT NOT NULL,session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE,payload_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('in_progress','succeeded','failed')),safe_response_json TEXT,error_json TEXT,expires_at TEXT NOT NULL,PRIMARY KEY(owner_id,request_id));
CREATE TABLE runs(id TEXT PRIMARY KEY,session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE,owner_id TEXT REFERENCES owners(id) ON DELETE CASCADE,request_id TEXT NOT NULL,workflow TEXT NOT NULL,lease_token TEXT NOT NULL UNIQUE,start_version INTEGER,reserved_version INTEGER,deadline_at TEXT NOT NULL,status TEXT NOT NULL,run_json TEXT NOT NULL);
CREATE TABLE node_runs(run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE,node_key TEXT NOT NULL,attempt INTEGER NOT NULL,input_hash TEXT NOT NULL,model_id TEXT NOT NULL,prompt_version TEXT NOT NULL,status TEXT NOT NULL,output_json TEXT,usage_json TEXT,started_at TEXT NOT NULL,finished_at TEXT,PRIMARY KEY(run_id,node_key,attempt));
CREATE TABLE events(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,seq INTEGER NOT NULL,event_type TEXT NOT NULL,subject_id TEXT NOT NULL,dependency_ids_json TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,invalidated INTEGER NOT NULL DEFAULT 0,UNIQUE(session_id,seq));
CREATE TABLE media(id TEXT PRIMARY KEY,owner_id TEXT REFERENCES owners(id) ON DELETE CASCADE,session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE,purpose TEXT NOT NULL CHECK(purpose IN('bank','handwriting')),private_path TEXT NOT NULL,content_hash TEXT NOT NULL,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,expires_at TEXT,CHECK((purpose='handwriting' AND owner_id IS NOT NULL AND expires_at IS NOT NULL) OR purpose='bank'));
CREATE TABLE transcripts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES owners(id) ON DELETE CASCADE,session_id TEXT REFERENCES sessions(id) ON DELETE CASCADE,media_id TEXT REFERENCES media(id) ON DELETE SET NULL,revision INTEGER NOT NULL,draft_json TEXT NOT NULL,confirmed INTEGER NOT NULL DEFAULT 0,expires_at TEXT);
CREATE TABLE submission_revisions(submission_id TEXT NOT NULL,revision INTEGER NOT NULL,session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,submission_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(submission_id,revision));
CREATE TABLE probe_counters(session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,task_id TEXT NOT NULL,canonical_goal_key TEXT NOT NULL,shown_count INTEGER NOT NULL DEFAULT 0 CHECK(shown_count BETWEEN 0 AND 2),PRIMARY KEY(session_id,task_id,canonical_goal_key));
CREATE TABLE check_attempts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES owners(id) ON DELETE CASCADE,session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,task_hash TEXT NOT NULL,equivalence_group TEXT NOT NULL,attempt_json TEXT NOT NULL,UNIQUE(owner_id,task_hash));
CREATE TABLE seen_tasks(owner_id TEXT NOT NULL REFERENCES owners(id) ON DELETE CASCADE,task_hash TEXT NOT NULL,equivalence_group TEXT NOT NULL,source_session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,first_seen_at TEXT NOT NULL,PRIMARY KEY(owner_id,task_hash));
CREATE TABLE teacher_grants(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,teacher_cookie_hash TEXT,one_time_code_hash TEXT UNIQUE,used_at TEXT,expires_at TEXT NOT NULL);
CREATE INDEX sessions_owner_expiry ON sessions(owner_id,expires_at);
CREATE INDEX runs_status_deadline ON runs(status,deadline_at);
CREATE INDEX seen_owner_group ON seen_tasks(owner_id,equivalence_group);